input.command:
F=Ern/MemoryModel/Access/Preserve/Frames.lean; D=/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/ref/v01/frames-ax; mkdir -p $D; cp $F $D/FramesAx.lean
awk '
/^namespace Frames\.Witness/ {ns="Frames.Witness."; next}
/^end Frames\.Witness/ {ns=""; next}
/^namespace Frames$/ {ns="Frames."; next}
/^end Frames$/ {ns=""; next}
/^(private )?(theorem|def|abbrev) / { n=$2; if ($1=="private") n=$3; print "#print axioms Ern.MemoryModel.Access." ns n }
' $F > $D/cmds.txt
wc -l $D/cmds.txt
# insert before final end
sed -i '' '$d' $D/FramesAx.lean
cat $D/cmds.txt >> $D/FramesAx.lean
echo "end Ern.MemoryModel.Access" >> $D/FramesAx.lean
# The print commands are inside the namespace; full names still resolve
~/.elan/bin/lake env lean $D/FramesAx.lean 2>&1 | grep -v "^  " | grep -vE "depends on axioms: \[propext(, Quot.sound)?\]$|does not depend on any axioms" | head -40

